  const TYPICAL_ATTACK_SYSTEMS = Object.freeze(['强攻', '敏攻', '防御', '控制', '元素', '精神', '辅助', '治疗', '召唤', '食物']);

  function typicalAttackRatio(level = 1, system = '') {
    const name = TYPICAL_ATTACK_SYSTEMS.find(type => String(system || '').includes(type));
    const column = ratios => Number(ratios[name ? `${name}系` : '全部'] ?? ratios.全部 ?? 1);
    const rows = TYPICAL_ATTACK_RATIO_BY_LEVEL, index = rows.findIndex(([at]) => at >= level);
    if (index <= 0) return index < 0 ? column(rows[rows.length - 1][1]) : 1;
    const [lowLevel, low] = rows[index - 1], [highLevel, high] = rows[index], t = (level - lowLevel) / (highLevel - lowLevel);
    return Math.max(1, column(low) + (column(high) - column(low)) * t);
  }

  const ROUTINE_BASIC_ATTACK = Object.freeze({ 原型: '伤害结算', 目标: '单体', 威力倍率: 50, 伤害类型: '近身攻击', 攻击段数: 1 });
  const ROUTINE_ATTACK_WINDUP = 40;

  // A known unit's strongest routine attack over its basic attack, expected damage against itself (same level, so a
  // skill's resource drive is about 1 and the ratio is its power over the basic attack's), at least 1.
  function knownRoutineAttackRatio(unit = {}) {
    const expected = (effect, resourceDriveEnabled) => preview.calculateBaseDamage(effect, unit, unit, null, { resourceDriveEnabled, targetCount: 1 }) *
      preview.estimateHitProbability(unit, unit, effect);
    const basic = expected(ROUTINE_BASIC_ATTACK, false);
    if (!(basic > 0)) return 1;
    let best = basic;
    for (const skill of collectSkills(unit)) {
      const trigger = String(skill?.触发方式 || '').trim();
      if (trigger && !['主动', '主动释放'].includes(trigger) || String(skill?.承载方式 || '').trim() === '造物承载' ||
        Number(skill?.前摇 ?? 0) > ROUTINE_ATTACK_WINDUP) continue;
      best = Math.max(best, (Array.isArray(skill?._效果数组) ? skill._效果数组 : [])
        .filter(effect => String(effect?.原型 || '').trim() === '伤害结算' && !['自身', '友方'].includes(String(effect?.目标 || '').trim()) &&
          preview.effectConditionEnabled(effect, {}, unit, unit, {}))
        .reduce((sum, effect) => sum + expected(effect, true), 0));
    }
    return best / basic;
  }

  // The routine attack as an attack of the basic attack's shape whose expected damage is routine_attack_ratio times the
  // basic attack's: calculateDamageFormula scales by power / 100 up to 100 and by (power / 100)^0.25 beyond, and the
  // basic attack's 50 is 0.5. Without a ratio (units outside a decision world) it is the basic attack.
  const routineAttackEffects = new Map();
  function routineAttackEffect(source = {}) {
    const ratio = Math.round(Number(source?.routine_attack_ratio) * 100) / 100;
    if (!(ratio > 1)) return ROUTINE_BASIC_ATTACK;
    let effect = routineAttackEffects.get(ratio);
    if (!effect) {
      const powerRatio = 0.5 * ratio;
      routineAttackEffects.set(ratio, effect = Object.freeze({ ...ROUTINE_BASIC_ATTACK, 威力倍率: powerRatio <= 1 ? 100 * powerRatio : 100 * powerRatio ** 4 }));
    }
    return effect;
  }

  // 交手看清对手 (用户 2026-11-13："对手的实力按理来说经过几次交手后会逐渐清晰啊？最起码不会偏离太多"): what a side has seen
  // of an enemy is every hit settled between them in the battle so far, either way, landed or not; n of them draw the
  // enemy's pictured level, panel and resources toward the true ones by n / (n + BELIEF_EXCHANGE_PRIOR) — half after two
  // exchanges, three quarters after six. A starting value, set by its reading. Counted per ledger while it grows.
  const BELIEF_EXCHANGE_PRIOR = 2;
  // Exchanges an actor's acquaintance with an enemy is worth: a battle fought with it, and a relation (a close one — kin, friend,
  // teammate, master, rival — more); at most BELIEF_FAMILIAR_CAP (clarity 0.8).
  const BELIEF_FAMILIAR_BATTLE = 4, BELIEF_FAMILIAR_RELATION = 2, BELIEF_FAMILIAR_CLOSE = 4, BELIEF_FAMILIAR_CAP = 8,
    BELIEF_SENSE_FLOOR = 1000, BELIEF_SENSE_EXCHANGES = 2,
    // How much an enemy that has not seen the actor holds its routine skill back for a probe (the R20 reveal base).
    BELIEF_PROBE_SHARE = Number(root.__LWCS_TUNE__?.BELIEF_PROBE_SHARE ?? 0.7);
  const BELIEF_CLOSE_RELATION = /挚友|好友|朋友|恋|伴侣|夫|妻|兄|弟|姐|妹|父|母|儿|女|师|徒|队友|同伴|伙伴|搭档|宿敌|对手|亲密|同门|同学|同事/;
  // 跨场情报（信息模型 0c，用户 2026-11-17）: a battle fought with it fades — half of it a year of world time on (战斗历史.最近tick,
  // BELIEF_YEAR_TICKS), as the target grows and changes. Only those close to it on its own side (BELIEF_INTIMATE_RELATION: kin,
  // friends, teammates, master and pupil, lovers) know it as it is (beliefIntimate); a rival, an opponent and anyone it has fought
  // know it by what it has shown (战斗暴露, beliefKnowsExposure) and by the clarity of the exchanges.
  const BELIEF_YEAR_TICKS = 51840;
  const BELIEF_INTIMATE_RELATION = /挚友|好友|朋友|恋|伴侣|夫|妻|兄|弟|姐|妹|父|母|儿|女|师|徒|队友|同伴|伙伴|搭档|亲密|同门|同学/;
  const beliefRecordOf = (table, target) => [preview.unitName(target), preview.unitId(target)].map(name => String(name || '').trim()).filter(Boolean)
    .map(name => table?.[name]).find(Boolean);
  const beliefRelation = (observer, target) => String(beliefRecordOf(observer?.社交?.关系, target)?.关系 || '').trim();
  function beliefIntimate(observer = {}, target = {}) {
    const relation = beliefRelation(observer, target);
    return !!relation && relation !== '陌生' && !/宿敌|对手|仇/.test(relation) && BELIEF_INTIMATE_RELATION.test(relation);
  }
  function beliefKnowsExposure(observer = {}, target = {}, world = {}) {
    const relation = beliefRelation(observer, target);
    return Number(beliefRecordOf(observer?.战斗历史 || observer?.属性?.战斗历史, target)?.次数 || 0) > 0 || !!relation && relation !== '陌生' ||
      !!(world?.赛事上下文 && typeof world.赛事上下文 === 'object');
  }
  function beliefFamiliarExchanges(observer = {}, target = {}, world = {}) {
    const relation = beliefRelation(observer, target);
    const record = beliefRecordOf(observer?.战斗历史 || observer?.属性?.战斗历史, target);
    const battles = Number(record?.次数 || 0);
    const now = Number(world?.当前世界tick ?? world?.当前tick ?? 0), then = Number(record?.最近tick || 0);
    const fade = now > 0 && then > 0 && now > then ? 0.5 ** ((now - then) / BELIEF_YEAR_TICKS) : 1;
    let prior = battles > 0 ? BELIEF_FAMILIAR_BATTLE * fade : 0;
    if (relation && relation !== '陌生') prior += BELIEF_CLOSE_RELATION.test(relation) ? BELIEF_FAMILIAR_CLOSE : BELIEF_FAMILIAR_RELATION;
    return Math.min(BELIEF_FAMILIAR_CAP, prior);
  }
  // 系别信念（信息模型 0b，用户 2026-11-17「根据释放的魂技原型可进一步加深判断」）: what one sees of a skill an enemy releases —
  // the kind of its first (main) effect: 伤害 (on an enemy), 硬控 / 软控 (a state, interference or debuff on an enemy: one that
  // takes the turn, or one that does not), 治疗 (HP back to one's side), 自身增益 / 友方增益 (a buff, shield or modifier on
  // itself / its side), 召唤, 造物, 其他. The likelihood of each kind by system is SKILL_CLASS_LIKELIHOOD (the game's generator).
  // 系别信念（信息模型 0b，用户 2026-11-17「开武魂后对方能看出自己武魂倾向……根据倾向猜测自身是什么系别……根据释放的魂技原型
