      const key = `${own}|${preview.unitId(actorUnit)}`;
      let alone = bySide.get(key);
      if (!alone) {
        alone = {};
        r20Race(table, own, { leaves: table.units.map((unit, row) => (row === actorRow ? 0 : Infinity)), report: alone });
        bySide.set(key, alone);
      }
